<span class="line"><span style="color:#24292E;">      </span><span style="color:#005CC5;">&quot;design_name&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;ML-0B-5&quot;</span><span style="color:#24292E;">,</span></span>
